mapper.select:
SELECT 
FROM note
WHERE deleted = 0

    AND user_id = #{userId}


    AND category = #{category}


    AND MATCH(title, summary) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE)


    AND EXISTS (
        SELECT 1 FROM note_tag_rel r
        JOIN tag t ON r.tag_id = t.id
        WHERE r.note_id = note.id AND t.name = #{tag}
    )

ORDER BY pinned DESC, updated_at DESC
